-- Element 6 2027 Battle Pass and holiday rewards.
-- Run after the account progress and social setup migrations. All grants are server catalog
-- lookups, authenticated, row-locked and idempotent. Public title labels are synced from
-- the account-owned equipped title so profile rows cannot publish an unowned title.

begin;

create table if not exists public.element6_season_reward_catalog (
  event_id text not null,
  event_kind text not null check (event_kind in ('battle-pass','holiday')),
  event_name text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  reward jsonb not null,
  tier smallint not null check (tier between 1 and 50),
  primary key (event_id, tier),
  check (starts_at <= ends_at)
);

create table if not exists public.element6_season_event_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  event_id text not null,
  xp integer not null default 0 check (xp >= 0),
  updated_at timestamptz not null default now(),
  primary key (user_id, event_id)
);

create table if not exists public.element6_season_xp_awards (
  user_id uuid not null references auth.users(id) on delete cascade,
  event_id text not null,
  match_id uuid not null,
  xp integer not null check (xp between 1 and 300),
  created_at timestamptz not null default now(),
  primary key (user_id, event_id, match_id)
);

create table if not exists public.element6_season_reward_claims (
  user_id uuid not null references auth.users(id) on delete cascade,
  event_id text not null,
  tier smallint not null,
  reward_id text not null,
  claimed_at timestamptz not null default now(),
  primary key (user_id, event_id, tier),
  foreign key (event_id, tier) references public.element6_season_reward_catalog(event_id, tier)
);


alter table public.player_profiles add column if not exists profile_title text;

create or replace function public.element6_sync_public_profile_title()
returns trigger
language plpgsql
security definer
set search_path = ''
as $E6PROFILETITLE$
declare
  v_title text;
begin
  select nullif(p.progress_json->>'equippedTitle','')
    into v_title
  from public.user_progress p
  where p.user_id = new.user_id;
  new.profile_title := v_title;
  return new;
end;
$E6PROFILETITLE$;

drop trigger if exists element6_sync_public_profile_title on public.player_profiles;
create trigger element6_sync_public_profile_title
before insert or update on public.player_profiles
for each row execute function public.element6_sync_public_profile_title();

alter table public.element6_season_reward_catalog enable row level security;
alter table public.element6_season_event_progress enable row level security;
alter table public.element6_season_xp_awards enable row level security;
alter table public.element6_season_reward_claims enable row level security;

revoke all on public.element6_season_reward_catalog from public, anon, authenticated;
revoke all on public.element6_season_event_progress from public, anon, authenticated;
revoke all on public.element6_season_xp_awards from public, anon, authenticated;
revoke all on public.element6_season_reward_claims from public, anon, authenticated;

