ends_at":"2028-01-03T23:59:59.999Z","reward":{"tier":4,"id":"new-year-2028-t4-shikigami-toki-clockwork-fox-with-golden-gears","type":"shikigami","name":"Toki","description":"clockwork fox with golden gears","shikigamiId":"shikigami-toki"}},{"event_id":"new-year-2028","event_kind":"holiday","event_name":"Six... Five... Four...","starts_at":"2027-12-27T00:00:00.000Z","ends_at":"2028-01-03T23:59:59.999Z","reward":{"tier":5,"id":"new-year-2028-t5-title-first-legend-of-2028","type":"title","name":"First Legend of 2028","titleId":"title-first-legend-of-2028"}},{"event_id":"new-year-2028","event_kind":"holiday","event_name":"Six... Five... Four...","starts_at":"2027-12-27T00:00:00.000Z","ends_at":"2028-01-03T23:59:59.999Z","reward":{"tier":6,"id":"new-year-2028-t6-shikigami-toshigami-new-year-spirit-with-golden-aura","type":"shikigami","name":"Toshigami","description":"New Year spirit with golden aura","shikigamiId":"shikigami-toshigami"}}]$e6catalog$::jsonb
  )
)
insert into public.element6_season_reward_catalog(event_id,event_kind,event_name,starts_at,ends_at,tier,reward)
select
  row->>'event_id',
  row->>'event_kind',
  row->>'event_name',
  (row->>'starts_at')::timestamptz,
  (row->>'ends_at')::timestamptz,
  ((row->'reward'->>'tier')::integer)::smallint,
  row->'reward'
from seed
on conflict(event_id,tier) do update set
  event_kind=excluded.event_kind,
  event_name=excluded.event_name,
  starts_at=excluded.starts_at,
  ends_at=excluded.ends_at,
  reward=excluded.reward;

create or replace function public.element6_award_season_xp_v1(
  p_event_ids text[],
  p_xp integer,
  p_match_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $E6XP$
declare
  v_user uuid := (select auth.uid());
  v_event text;
  v_event_row public.element6_season_reward_catalog%rowtype;
  v_daily integer;
  v_grant integer;
  v_awards jsonb := '[]'::jsonb;
  v_xp integer;
  v_progress jsonb;
  v_updated timestamptz;
  v_claimed jsonb;
begin
  if v_user is null then raise exception 'Sign in to save seasonal progress'; end if;
  if p_match_id is null or p_xp is null or p_xp < 1 or p_xp > 300 then
    raise exception 'Invalid seasonal match award';
  end if;
  if coalesce(cardinality(p_event_ids),0) = 0 or cardinality(p_event_ids) > 2 then
    raise exception 'Invalid active reward tracks';
  end if;

  foreach v_event in array p_event_ids loop
    select * into v_event_row
    from public.element6_season_reward_catalog c
    where c.event_id=v_event
    order by c.tier
    limit 1;
    if v_event_row.event_id is null or clock_timestamp() < v_event_row.starts_at or clock_timestamp() > v_event_row.ends_at then
      continue;
    end if;

    -- Serialize awards per player and event so concurrent match callbacks
    -- cannot race past the daily XP ceiling.
    insert into public.element6_season_event_progress(user_id,event_id,xp)
    values(v_user,v_event,0) on conflict(user_id,event_id) do nothing;
    select p.xp into v_xp
    from public.element6_season_event_progress p
    where p.user_id=v_user and p.event_id=v_event
    for update;

    select coalesce(sum(a.xp),0)::integer into v_daily
    from public.element6_season_xp_awards a
    where a.user_id=v_user and a.event_id=v_event
      and a.created_at >= date_trunc('day',clock_timestamp() at time zone 'UTC') at time zone 'UTC';

    v_grant := least(p_xp, greatest(0, 3000-v_daily));
    if v_grant > 0 then
      insert into public.element6_season_xp_awards(user_id,event_id,match_id,xp)
      values(v_user,v_event,p_match_id,v_grant)
      on conflict(user_id,event_id,match_id) do nothing;
      if found then
        insert into public.element6_season_event_progress(user_id,event_id,xp,updated_at)
        values(v_user,v_event,v_grant,clock_timestamp())
        on conflict(user_id,event_id) do update
          set xp=public.element6_season_event_progress.xp+excluded.xp,
              updated_at=excluded.updated_at;
      end if;
    end if;

    select p.xp into v_xp
    from public.element6_season_event_progress p
    where p.user_id=v_user and p.event_id=v_event;
    select coalesce(jsonb_agg(c.tier order by c.tier),'[]'::jsonb) into v_claimed
    from public.element6_season_reward_claims c
    where c.user_id=v_user and c.event_id=v_event;
    insert into public.user_progress(user_id,progress_json,updated_at)
    values(v_user,'{}'::jsonb,clock_timestamp()) on conflict(user_id) do nothing;
    select progress_json into v_progress from public.user_progress where user_id=v_user for update;
    v_progress := coalesce(v_progress,'{}'::jsonb);
    if jsonb_typeof(v_progress->'eventProgress') is distinct from 'object' then
      v_progress := jsonb_set(v_progress,'{eventProgress}','{}'::jsonb,true);
    end if;
    v_progress := jsonb_set(v_progress,array['eventProgress',v_event],
      jsonb_build_object('xp',coalesce(v_xp,0),'claimedTiers',v_claimed),true);
    v_updated := clock_timestamp();
    update public.user_progress set progress_json=v_progress,updated_at=v_updated where user_id=v_user;
    v_awards := v_awards || jsonb_build_array(jsonb_build_object('event_id',v_event,'xp',coalesce(v_xp,0)));
  end loop;

  return jsonb_build_object('awards',v_awards,'progress',coalesce(v_progress,'{}'::jsonb),'updated_at',v_updated);
end;
$E6XP$;

create or replace function public.claim_element6_event_reward_v1(
  p_event_id text,
  p_tier integer
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $E6CLAIM$
declare
  v_user uuid := (select auth.uid());
  v_event public.element6_season_reward_catalog%rowtype;
  v_event_progress public.element6_season_event_progress%rowtype;
  v_claim public.element6_season_reward_claims%rowtype;
  v_progress jsonb;
  v_array jsonb;
  v_claimed jsonb;
  v_reward_id text;
  v_kind text;
  v_amount integer;
  v_updated timestamptz;
begin
  if v_user is null then raise exception 'Sign in to claim event rewards'; end if;
  if p_event_id is null or p_tier is null or p_tier < 1 or p_tier > 50 then
    raise exception 'Invalid event reward';
  end if;

  select * into v_event
  from public.element6_season_reward_catalog
  where event_id=p_event_id and tier=p_tier;
  if v_event.event_id is null then raise exception 'Reward not found'; end if;
  if clock_timestamp() < v_event.starts_at or clock_timestamp() > v_event.ends_at then
    raise exception 'This event is not active';
  end if;

  insert into public.element6_season_event_progress(user_id,event_id,xp)
  values(v_user,p_event_id,0)
  on conflict(user_id,event_id) do nothing;
  select * into v_event_progress
  from public.element6_season_event_progress
  where user_id=v_user and event_id=p_event_id
  for update;
  if coalesce(v_event_progress.xp,0) < (p_tier*1000) then
    raise exception 'Earn more Event XP to unlock this reward';
  end if;

  select * into v_claim
  from public.element6_season_reward_claims
  where user_id=v_user and event_id=p_event_id and tier=p_tier;
  if v_claim.user_id is not null then
    select progress_json,updated_at into v_progress,v_updated
    from public.user_progress where user_id=v_user;
    return jsonb_build_object('claimed',false,'already_claimed',true,
      'event_id',p_event_id,'tier',p_tier,'xp',v_event_progress.xp,
      'claimed_tiers',coalesce((select jsonb_agg(c.tier order by c.tier)
        from public.element6_season_reward_claims c
        where c.user_id=v_user and c.event_id=p_event_id),'[]'::jsonb),
      'progress',coalesce(v_progress,'{}'::jsonb),'updated_at',v_updated);
  end if;

  insert into public.user_progress(user_id,progress_json,updated_at)
  values(v_user,'{}'::jsonb,clock_timestamp())
  on conflict(user_id) do nothing;
  select progress_json into v_progress
  from public.user_progress where user_id=v_user for update;
  v_progress := coalesce(v_progress,'{}'::jsonb);
  v_reward_id := v_event.reward->>'id';
  v_kind := v_event.reward->>'type';
  v_amount := coalesce((v_event.reward->>'amount')::integer,0);

  insert into public.element6_season_reward_claims(user_id,event_id,tier,reward_id)
  values(v_user,p_event_id,p_tier,v_reward_id);

  -- Keep a typed ownership ledger so every reward has a durable account entry.
  v_array := coalesce(v_progress->'ownedEventRewards','[]'::jsonb);
  if not v_array @> jsonb_build_array(v_reward_id) then
    v_progress := jsonb_set(v_progress,'{ownedEventRewards}',v_array || jsonb_build_array(v_reward_id),true);
  end if;

  if v_kind='tokens' then
    v_progress := jsonb_set(v_progress,'{coins}',to_jsonb(coalesce((v_progress->>'coins')::integer,0)+v_amount),true);
  elsif v_kind='title' then
    v_array := coalesce(v_progress->'ownedTitles','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_event.reward->>'titleId') then
      v_progress := jsonb_set(v_progress,'{ownedTitles}',v_array || jsonb_build_array(v_event.reward->>'titleId'),true);
    end if;
  elsif v_kind='shikigami' then
    v_array := coalesce(v_progress->'ownedShikigami','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_event.reward->>'shikigamiId') then
      v_progress := jsonb_set(v_progress,'{ownedShikigami}',v_array || jsonb_build_array(v_event.reward->>'shikigamiId'),true);
    end if;
  elsif v_kind='accessory' then
    v_array := coalesce(v_progress->'ownedAccessories','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_reward_id) then
      v_progress := jsonb_set(v_progress,'{ownedAccessories}',v_array || jsonb_build_array(v_reward_id),true);
    end if;
  elsif v_kind='ko' then
    v_array := coalesce(v_progress->'ownedKillFX','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_reward_id) then
      v_progress := jsonb_set(v_progress,'{ownedKillFX}',v_array || jsonb_build_array(v_reward_id),true);
    end if;
  elsif v_kind='emote' then
    v_array := coalesce(v_progress->'ownedEmotes','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_reward_id) then
      v_progress := jsonb_set(v_progress,'{ownedEmotes}',v_array || jsonb_build_array(v_reward_id),true);
    end if;
  elsif v_kind='trail' then
    v_array := coalesce(v_progress->'ownedTrails','[]'::jsonb);
    if not v_array @> jsonb_build_array(v_reward_id) then
      v_progress := jsonb_set(v_progress,'{ownedTrails}',v_array || jsonb_build_array(v_reward_id),true);
    end if;
  end if;

  v_claimed := coalesce((select jsonb_agg(c.tier order by c.tier)
    from public.element6_season_reward_claims c
    where c.user_id=v_user and c.event_id=p_event_id),'[]'::jsonb);
  if jsonb_typeof(v_progress->'eventProgress') is distinct from 'object' then
    v_progress := jsonb_set(v_progress,'{eventProgress}','{}'::jsonb,true);
  end if;
  v_progress := jsonb_set(v_progress,
    array['eventProgress',p_event_id],
    jsonb_build_object('xp',v_event_progress.xp,'claimedTiers',v_claimed),true);
  v_updated := clock_timestamp();
  update public.user_progress set progress_json=v_progress,updated_at=v_updated where user_id=v_user;

  return jsonb_build_object('claimed',true,'already_claimed',false,
    'event_id',p_event_id,'tier',p_tier,'reward',v_event.reward,
    'xp',v_event_progress.xp,'claimed_tiers',v_claimed,
    'progress',v_progress,'updated_at',v_updated);
end;
$E6CLAIM$;

create or replace function public.element6_equip_owned_title_v1(p_title_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $E6TITLE$
declare
  v_user uuid := (select auth.uid());
  v_progress jsonb;
  v_updated timestamptz := clock_timestamp();
  v_title text := nullif(trim(coalesce(p_title_id,'')),'');
begin
  if v_user is null then raise exception 'Sign in to equip a profile title'; end if;
  insert into public.user_progress(user_id,progress_json,updated_at)
  values(v_user,'{}'::jsonb,v_updated) on conflict(user_id) do nothing;
  select progress_json into v_progress
  from public.user_progress where user_id=v_user for update;
  v_progress := coalesce(v_progress,'{}'::jsonb);

  if v_title is not null then
    if v_title not in ('founder','hero','villain','guardian','legend','champion','mvp','veteran','collector')
      and not exists (
      select 1 from public.element6_season_reward_catalog c
      where c.reward->>'titleId'=v_title and c.reward->>'type'='title'
    ) then raise exception 'Title not found'; end if;
    if not (coalesce(v_progress->'ownedTitles','[]'::jsonb) @> jsonb_build_array(v_title)
      or coalesce(v_progress->'ownedPacks','[]'::jsonb) @> '["all_titles"]'::jsonb) then
      raise exception 'You do not own this title';
    end if;
  end if;

  v_progress := jsonb_set(v_progress,'{equippedTitle}',coalesce(to_jsonb(v_title),'null'::jsonb),true);
  update public.user_progress set progress_json=v_progress,updated_at=v_updated where user_id=v_user;
  update auth.users
  set raw_user_meta_data=jsonb_set(coalesce(raw_user_meta_data,'{}'::jsonb),'{profile_title}',coalesce(to_jsonb(v_title),'""'::jsonb),true),
      updated_at=v_updated
  where id=v_user;
  update public.player_profiles set profile_title=v_title,updated_at=v_updated where user_id=v_user;

  return jsonb_build_object('saved',true,'title_id',v_title,'progress',v_progress,'updated_at',v_updated);
end;
$E6TITLE$;

revoke all on function public.element6_award_season_xp_v1(text[],integer,uuid) from public,anon;
revoke all on function public.claim_element6_event_reward_v1(text,integer) from public,anon;
revoke all on function public.element6_equip_owned_title_v1(text) from public,anon;
grant execute on function public.element6_award_season_xp_v1(text[],integer,uuid) to authenticated;
grant execute on function public.claim_element6_event_reward_v1(text,integer) to authenticated;
grant execute on function public.element6_equip_owned_title_v1(text) to authenticated;

commit;

